function campaignCatalogueActive(state=S){return [3,4,5,6].includes(state?.enemyRosterVersion)&&!state.tutorial&&modernJourney(state)&&journeyLength(state)===campaignLength(state.campaign)}
function campaignEncounterPlan(chapter=S.round,path=S.pathChoice){
 const ci=['crown','rift','frost','embers','depths','eclipse'].indexOf(S.campaign),boss=bossNumber(chapter);
 if(campaignSmoothingActive()&&S.campaign==='eclipse'&&chapter===23)return {name:path==='risk'?'Nachtwache am letzten Tor':'Wächter vor dem Morgengrauen',plan:path==='risk'?['shield','raider','warden','mage','ritual','archer']:['shield','breaker','warden','mage','scout','archer'],hint:path==='risk'?'Drei Frontwachen decken den Kanalisierer. Sein Ritual kommt in Runde 3; Durchbruch und Lähmung helfen.':'Drei Frontwachen decken die Nachtmagie. Brich eine Bahn auf und erreiche die Hinterreihe.'};
 if(boss){const plans=[['shield','raider','warden','archer','marshal','scout'],['beast','breaker','shield','mage','healer','archer'],['shield','breaker','warden','mage','healer','archer']];return {name:boss===3?'Die letzte Leibwache':boss===2?'Belagerungsstellung':'Torwache',plan:plans[boss-1],hint:boss===3?'Besiege die Leibwachen, bevor du den Endgegner direkt angreifen kannst.':'Zwischenboss und Begleiter halten den Durchgang. Prüfe ihre angekündigte Bossregel.'}}
 const sharedRift=campaignSmoothingActive()&&S.campaign==='rift',n=chapter-1-bossChapters().filter(ch=>ch<chapter).length,index=(n+ci*2+(path==='risk'&&!sharedRift?5:0))%CAMPAIGN_ENCOUNTER_PATTERNS.length;
 const pattern=CAMPAIGN_ENCOUNTER_PATTERNS[index],shift=(Math.floor(n/12)+ci+(path==='risk'&&!sharedRift?1:0))%3,plan=Array(6).fill(null);
 pattern.plan.forEach((role,i)=>{plan[Math.floor(i/3)*3+(i%3+shift)%3]=role});return {...pattern,name:sharedRift&&path==='risk'?pattern.name+' · versetzte Hinterreihe':pattern.name,hint:sharedRift&&path==='risk'?pattern.hint+' Die verstärkte Hinterreihe wechselt ihre Bahnen.'+(chapter===9?' Ein Kanalisierer löst in Runde 3 sein Ritual aus.':''):pattern.hint,index,shift,plan};
}
function campaignCatalogueEnemies(chapter){
 const pattern=campaignEncounterPlan(chapter),scaled=encounterScale(chapter),cap=scaled<3?2:scaled<5?3:Math.min(6,fieldLimit(chapter)+(bossNumber(chapter)?1:0));
 const order=[0,4,1,3,2,5],slots=order.filter(i=>pattern.plan[i]).slice(0,cap),risky=S.pathChoice==='risk';
 const units=pattern.plan.map((role,i)=>{if(!role||!slots.includes(i))return null;const rank=slots.indexOf(i),upgrades=Math.max(0,Math.floor((scaled-5)/2)),thirds=Math.max(0,Math.floor((scaled-16)/2));return {id:`foe_${S.campaign}_${role}`,lv:thirds>rank?3:upgrades>rank?2:1,elite:!!bossNumber(chapter)&&rank===0,pathElite:risky}});
 // Only new catalogue-v4 journeys: ease one late front obstacle, retain the formation's other threats.
 const relief={crown:[11],embers:[23],depths:[23],eclipse:[20,21,22,23]};
 if([4,5,6].includes(S.enemyRosterVersion)&&relief[S.campaign]?.includes(chapter)&&!bossNumber(chapter)){const first=units.findIndex((u,i)=>u&&i<3);if(first>=0)units[first].lv=Math.min(2,units[first].lv)}
 if(campaignSmoothingActive())smoothCampaignFormation(units,chapter);
 return finalBossFormation(units,chapter);
}

// Versioned NPC-only pressure: keep historical journeys and player cards untouched.
function campaignSmoothingActive(state=S){return [5,6].includes(state?.enemyRosterVersion)&&!state.tutorial&&modernJourney(state)&&journeyLength(state)===campaignLength(state.campaign)}
function campaignBossType(b,state=S){if(state&&!campaignSmoothingActive(state))return b;const changes={frost:{hp:127,atk:17},embers:{hp:150,atk:18},depths:{hp:151,atk:19},eclipse:{hp:162,atk:26}};return changes[b.campaign]?{...b,...changes[b.campaign]}:b}
function smoothCampaignFormation(units,chapter){
 const camp=S.campaign,risk=S.pathChoice==='risk',boss=bossNumber(chapter),cap=(slots,level)=>slots.forEach(i=>{if(units[i])units[i].lv=Math.min(level,units[i].lv)});
 if(!boss){
  if(camp==='crown'&&chapter===11)cap([4],2);
  if(camp==='rift'&&[10,11].includes(chapter))cap([0,4],2);
  if(camp==='rift'&&risk){const rear=units.slice(3);[units[3],units[4],units[5]]=[rear[2],rear[0],rear[1]];if(chapter===9){const at=units.findIndex(u=>u?.id==='foe_rift_mage');if(at>=0)units[at].id='foe_rift_ritual'}}
  if(camp==='frost'&&risk&&chapter===15)cap([0,1],2);
  if(camp==='embers'&&chapter===22)cap([0,1,3,4],2);
  if(camp==='depths'&&((risk&&chapter>=19)||(chapter>=22)))cap([0,1,2],2);
  if(camp==='eclipse'&&chapter===22)cap([1],2);
  if(camp==='eclipse'&&chapter===23){cap([0,2,4],2);if(units[3])units[3].lv=3}
 }
 if(camp==='frost'&&boss===2&&units[5])units[5].lv=2;
 let hp=1;
 if(!boss&&camp==='crown'&&chapter===11)hp=.92;
 if(!boss&&camp==='rift'&&[10,11].includes(chapter))hp=.95;
 if(camp==='frost'&&chapter>=8&&chapter<=13)hp=1.22;
 if(!boss&&camp==='frost'&&chapter===14)hp=.95;
 if(!boss&&camp==='embers'&&chapter>=12&&chapter<=20)hp=1.15;
 if(!boss&&camp==='depths'&&chapter>=14&&chapter<=18)hp=1.08;
 if(S.enemyRosterVersion===6&&!boss){
  if(camp==='embers'&&chapter===22){if(units[1])units[1].lv=3;if(units[4])units[4].lv=3}
  if(camp==='embers'&&risk&&chapter===23)cap([4],2);
 }
 if(hp!==1)units.forEach(u=>{if(u)u.campaignHealthFactor=hp});
}

function campaignEnemyRule(u){return CAMPAIGN_ENEMIES[u.id].cardText}
function campaignEnemyAttackFactor(u){const mechanic=CAMPAIGN_ENEMIES[u.id]?.mechanic;if(mechanic==='ritual')return 0;if(mechanic==='fatigue')return u.attackCount?.65:1;if(mechanic==='tide')return (u.enemyRound||1)%2?0:.65;if(mechanic==='dawn')return (u.enemyRound||1)%2?.7:1;return 1}
function campaignEnemyStatus(u,round){const t=CAMPAIGN_ENEMIES[u.id];if(!t)return '';if(t.mechanic==='ritual')return round%3===0?'Ritual jetzt: lähmen oder töten!':`Ritual in Runde ${round+3-round%3}`;if(t.mechanic==='fatigue')return u.attackCount?'Erschöpft · 65 % Angriff':'Erstschlag · volle Stärke';if(t.mechanic==='tide')return round%2?'Schutzphase · kein Angriff':'Deckung offen · schwacher Angriff';if(t.mechanic==='thaw')return `Tauender Schild · 🛡${u.shield||0}`;if(t.mechanic==='dawn')return round%2?'Nacht · schwächerer Angriff':'Morgen · voller Angriff';return t.role==='Heilung'?(round%2?'Heilung in gerader Runde':'Heilung und Angriff'):''}
function campaignEnemyRound(units,round,logs){for(const u of units.filter(u=>u&&u.hp>0&&CAMPAIGN_ENEMIES[u.id])){u.enemyRound=round;const mechanic=CAMPAIGN_ENEMIES[u.id].mechanic;if(mechanic==='thaw'&&round>=2&&round<=3){const melt=Math.min(4,u.shield||0);u.shield-=melt;logs.push(`${type(u).name}: ${melt} Schild schmilzt.`)}if(mechanic==='tide'){u.shield=round%2?(u.shield||0)+6:Math.max(0,(u.shield||0)-6);logs.push(`${type(u).name}: ${campaignEnemyStatus(u,round)}.`)}if(mechanic==='ritual')logs.push(`${type(u).name}: ${campaignEnemyStatus(u,round)}.`)}}
function campaignEnemyAction(actor,other,round,logs){const t=CAMPAIGN_ENEMIES[actor.id];if(!t||actor.hp<=0)return false;if(t.mechanic==='tide'&&round%2){logs.push(`${t.name} hält seine Deckung.`);return true}if(t.mechanic!=='ritual')return false;if(round%3===0&&actor.ritualRound!==round){actor.ritualRound=round;const damage=2+2*upgradeRank(actor);other.filter(u=>u&&u.hp>0).forEach(u=>damageUnit(u,damage,actor));logs.push(`${t.name}: Ritual trifft alle lebenden Truppen für ${damage} Schaden.`)}return true}
